    "author": "José Nizzo",
    "date": "2025-09-17T08:48:00",
    "image": "https://josenizzo.info/wp-content/uploads/2025/09/ChatGPT-Image-17-sept-2025-13_45_36.png",
    "featured": false,
    "breaking": false,
    "badge": "analysis",
    "readTime": 2,
    "views": 12558
