    "author": "José Nizzo",
    "date": "2025-06-17T14:54:31",
    "image": "https://josenizzo.info/wp-content/uploads/2025/06/5659064345778300897.jpg",
    "featured": false,
    "breaking": false,
    "badge": "exclusive",
