    "author": "José Nizzo",
    "date": "2025-06-16T18:59:47",
    "image": "https://josenizzo.info/wp-content/uploads/2025/06/anses91f71ecd52101974.webp",
    "featured": false,
    "breaking": false,
    "badge": null,
